} else {
  notifySubject =
    "Added to Trek: " + (ex.provider_name || ex.booking_type || "Booking")
  notifyText =
    (createdNewTrip
      ? "Created a new trip and added this booking."
      : "Added this booking to an existing trip.") +
    "\n\n" +
    "Trip: https://${TREK_SUBDOMAIN}.${SECRET_DOMAIN}/trips/" +
    tripId +
    "\n" +
